class Solution {
  public String smallestSubsequence(String s, int k, char letter, int repetition) {
    int n = s.length(), lettersLeft = 0;
    for (int i = 0; i < n; i++) if (s.charAt(i) == letter) lettersLeft++;
    char[] stack = new char[n];
    int size = 0, lettersInStack = 0;
    for (int i = 0; i < n; i++) {
      char c = s.charAt(i);
      while (size > 0 && stack[size - 1] > c && size + n - i - 1 >= k) {
        if (stack[size - 1] == letter) {
          if (lettersInStack + lettersLeft - 1 < repetition) break;
          lettersInStack--;
        }
        size--;
      }
      if (size < k) {
        if (c == letter) {
          stack[size++] = c;
          lettersInStack++;
        } else if (k - size > Math.max(0, repetition - lettersInStack)) {
          stack[size++] = c;
        }
      }
      if (c == letter) lettersLeft--;
    }
    return new String(stack, 0, size);
  }
}
